def format_cell(storage, value, levels):
    if storage == "factor":
        if value is None:
            return "NA"
        return str(levels[int(value) - 1])
    if value is None:
        return "NA"
    if storage == "logical":
        return "TRUE" if value else "FALSE"
    if storage == "integer":
        return str(int(value))
    if storage == "double":
        if value != value:
            return "NaN"
        if value == float("inf"):
            return "Inf"
        if value == float("-inf"):
            return "-Inf"
        text = format(float(value), ".17g")
        return text
    return str(value)


def format_table(df):
    names = [name for name, _ in df.columns]
    rendered = []
    for _name, column in df.columns:
        levels = column.attributes.get("levels", []) if is_factor(column) else None
        storage = "factor" if is_factor(column) else column.storage
        rendered.append([format_cell(storage, value, levels) for value in column.values])
    width = [max([len(name)] + [len(item) for item in col]) for name, col in zip(names, rendered)]
    lines = ["  ".join(name.rjust(size) for name, size in zip(names, width))]
    for index in range(df.nrows):
        lines.append("  ".join(rendered[col][index].rjust(width[col]) for col in range(len(names))))
    return "\n".join(lines)


def section(title, df):
    return title + "\n" + format_table(df)


def examples():
    values = list(range(1, 24)) + [None]
    array = np.array(values, dtype=object).reshape((2, 3, 4), order="F")
    letters = [list("AB"), list("ABC"), list("ABCD")]
    blocks = [
        section("melt(a)", melt(array)),
        section("melt(a, na.rm = TRUE)", melt(array, na_rm=True)),
        section('melt(a, varnames=c("X","Y","Z"))', melt(array, varnames=["X", "Y", "Z"])),
        section("melt(a) after dimnames", melt(Array(array, dimnames=letters))),
        section('melt(a, varnames=c("X","Y","Z")) after dimnames', melt(Array(array, dimnames=letters), varnames=["X", "Y", "Z"])),
        section("melt(a) with the first dimname removed", melt(Array(array, dimnames=[None, list("ABC"), list("ABCD")]))),
        section("melt(as.list(c(1:4, NA)))", melt(List([1, 2, 3, 4, None]))),
        section("melt(a) after names", melt(List([1, 2, 3, 4, None], names=["a", "b", "c", "d"]))),
        section(
            "melt(list(matrix(1:4, ncol=2), matrix(1:6, ncol=2)))",
            melt([
                np.array([1, 2, 3, 4]).reshape((2, 2), order="F"),
                np.array([1, 2, 3, 4, 5, 6]).reshape((3, 2), order="F"),
            ]),
        ),
        section(
            "melt(list(matrix(1:4, ncol=2), array(1:27, c(3,3,3))))",
            melt([
                np.array([1, 2, 3, 4]).reshape((2, 2), order="F"),
                np.arange(1, 28).reshape((3, 3, 3), order="F"),
            ]),
        ),
        section(
            "melt(list(1:5, matrix(1:4, ncol=2)))",
            melt([(1, 2, 3, 4, 5), np.array([1, 2, 3, 4]).reshape((2, 2), order="F")]),
        ),
        section(
            "melt(list(list(1:3), 1, list(as.list(3:4), as.list(1:2))))",
            melt([[(1, 2, 3)], 1.0, [[3, 4], [1, 2]]]),
        ),
        section('melt(airquality, id=c("month", "day"))', melt(AIR, id=["month", "day"])),
        section(
            "melt(ChickWeight, id=2:4)",
            melt(
                {
                    "weight": CHICK["weight"],
                    "time": CHICK["time"],
                    "chick": factor(CHICK["chick"], CHICK_LEVELS),
                    "diet": factor(CHICK["diet"], DIET_LEVELS),
                },
                id=[2, 3, 4],
            ),
        ),
    ]
    return "\n\n".join(blocks) + "\n"


out = Path(__file__).resolve().parents[1] / "docs" / "output" / "melt-python.txt"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(examples(), encoding="utf-8")

n = 4000
index = list(range(n))
frame = {
    "id": [k + 1 for k in index],
    "group": [f"g{k % 5}" for k in index],
    "a": [None if k % 11 == 0 else (k % 97) / 2 for k in index],
    "b": [None if k % 13 == 0 else float((k * 3) % 50) for k in index],
}


def one():
    return melt(frame, id=["id", "group"])


value = one()
elapsed = []
for _ in range(20):
    started = time.perf_counter()
    one()
    elapsed.append((time.perf_counter() - started) * 1000)


def emit(df):
    print(f"NROW {df.nrows}")
    for name, column in df.columns:
        if is_factor(column):
            levels = column.attributes.get("levels", [])
            print("COL " + name + " factor " + "|".join(str(level) for level in levels))
            vals = ["NA" if code is None else str(levels[int(code) - 1]) for code in column.values]
        elif column.storage == "character":
            print("COL " + name + " character ")
            vals = ["NA" if item is None else str(item) for item in column.values]
        elif column.storage == "integer":
            print("COL " + name + " integer ")
            vals = ["NA" if item is None else str(int(item)) for item in column.values]
        elif column.storage == "logical":
            print("COL " + name + " logical ")
            vals = ["NA" if item is None else ("TRUE" if item else "FALSE") for item in column.values]
        else:
            print("COL " + name + " double ")
            vals = []
            for item in column.values:
                if item is None:
                    vals.append("NA")
                elif item != item:
                    vals.append("NaN")
                elif item == float("inf"):
                    vals.append("Inf")
                elif item == float("-inf"):
                    vals.append("-Inf")
                else:
                    vals.append(format(float(item), ".17g"))
        print("\t".join(vals))


print(f"MEDIAN_MS {statistics.median(elapsed):.17g}")
emit(value)
